"""Shared plumbing for the :mod:`wsparse` entry points.

Every public entry point has to agree on three things:

* what a usable path is,
* when a failure is an ``"unsupported"`` failure rather than an ``"os"`` one,
* and that an unsupported object never gets a silent success.
"""

import os

from . import _winapi
from .errors import WSParseError


def normalise_path(path):
    """Return ``path`` as a string, rejecting values that cannot be a path."""
    try:
        return os.fspath(path)
    except TypeError as exc:
        raise WSParseError(
            "path must be a path-like object, got %r" % (path,), kind="badarg"
        ) from exc


def require_windows(path):
    """Raise an ``"unsupported"`` error when sparse files cannot exist here."""
    if not _winapi.is_windows():
        raise WSParseError(
            "sparse files are an NTFS concept and need a Windows kernel",
            kind="unsupported",
            path=path,
        )


def reject_non_file(path, must_exist=True):
    """Reject objects that can never carry sparse-file semantics.

    A directory is the canonical example: it exists, it has a path, but no
    sparse operation can ever apply to it.  That is an ``"unsupported"``
    failure, never a silent success.
    """
    if os.path.isdir(path):
        raise WSParseError(
            "not a regular file, sparse-file operations do not apply",
            kind="unsupported",
            path=path,
        )
    if must_exist and not os.path.exists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)


def wrap_os_error(exc, path):
    """Turn an :class:`OSError` into a classified :class:`WSParseError`."""
    if _winapi.is_unsupported_error(exc):
        return WSParseError(_message(exc), kind="unsupported", path=path)
    return WSParseError(_message(exc), kind="os", path=path)


def _message(exc):
    text = getattr(exc, "strerror", None) or str(exc)
    code = getattr(exc, "winerror", None)
    if code:
        return "%s (WinError %d)" % (text, code)
    return text


def round_up_to_cluster(value, path):
    """Round ``value`` up to a whole allocation unit of ``path``'s volume."""
    if value <= 0:
        return 0
    try:
        unit = _winapi.cluster_size(path)
    except OSError:
        unit = None
    if not unit or unit <= 1:
        return value
    blocks = (value + unit - 1) // unit
    return blocks * unit


class open_handle:
    """Context manager around a raw Win32 handle with classified errors."""

    def __init__(self, path, write=False, create=False):
        self._path = path
        self._write = write
        self._create = create
        self.handle = None

    def __enter__(self):
        try:
            self.handle = _winapi.open_file(
                self._path, write=self._write, create=self._create
            )
        except OSError as exc:
            raise wrap_os_error(exc, self._path) from exc
        return self.handle

    def __exit__(self, exc_type, exc, tb):
        if self.handle is not None:
            _winapi.close_file(self.handle)
            self.handle = None
        return False

"""Allocated-range reporting for sink files."""

from . import _winapi
from ._support import (
    normalise_path,
    open_handle,
    reject_non_file,
    require_windows,
    wrap_os_error,
)


def _normalise(raw, size):
    """Clamp ``raw`` to ``size``, then order and merge the ranges."""
    clean = []
    for offset, length in raw:
        if length <= 0 or offset >= size:
            continue
        if offset < 0:
            length += offset
            offset = 0
            if length <= 0:
                continue
        if offset + length > size:
            length = size - offset
        if length > 0:
            clean.append((offset, length))
    clean.sort()
    merged = []
    for offset, length in clean:
        if merged:
            last_offset, last_length = merged[-1]
            last_end = last_offset + last_length
            if offset <= last_end:
                end = max(last_end, offset + length)
                merged[-1] = (last_offset, end - last_offset)
                continue
        merged.append((offset, length))
    return merged


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is already allocated is on disk, everything else
    is a hole that still needs data.  The list is ordered by ``offset``, the
    ranges never overlap, and every range lies inside the file's logical
    length.

    A sink that is all hole reports an empty list.  A sink that is not sparse
    is backed end to end, so it reports a single range covering its length.
    """
    path = normalise_path(path)
    require_windows(path)
    reject_non_file(path, must_exist=True)

    with open_handle(path, write=False, create=False) as handle:
        try:
            size = _winapi.file_size(handle)
            if size <= 0:
                return []
            attributes = _winapi.file_attributes(path)
            if not attributes & _winapi.SPARSE_ATTRIBUTE:
                # Nothing about a dense file is a hole.
                return [(0, size)]
            raw = _winapi.query_allocated_ranges(handle, size)
        except OSError as exc:
            raise wrap_os_error(exc, path) from exc
    return _normalise(raw, size)

